tips.suggestion:
[重构思路] 在使用数组形式（即放弃 count）时要求必须有 dispatchSize，否则立即报错；或在 count 缺失时抛出可读异常而不是让 dispatchCount 变成 0。
代码示例：
```js
export const compute = ( node, countOrWorkgroupSize, workgroupSize ) => {

	const isWorkgroupForm = Array.isArray( countOrWorkgroupSize );
	const count = isWorkgroupForm ? null : countOrWorkgroupSize;
	if ( isWorkgroupForm ) workgroupSize = countOrWorkgroupSize;

	const computeNode = new ComputeNode( nodeObject( node ), count, workgroupSize );
	if ( isWorkgroupForm ) computeNode.dispatchCount = null; // 标记为“需显式 dispatchSize”
	return nodeObject( computeNode );

};
```
并在 backend/updateBefore 路径中当 dispatchCount == null 且未提供 dispatchSize 时 `throw new Error( 'compute(): dispatchSize is required when count is omitted' )`。

[重构思路] 把 dispatchSize 作为可选参数贯穿 compute → computeAsync，并在未初始化分支一并传递。
代码示例：
```js
compute( computeNodes, dispatchSize = [ 0, 0, 0 ] ) {

	if ( this._initialized === false ) {

		console.warn( '... Try using .computeAsync() instead.' );
		return this.computeAsync( computeNodes, dispatchSize );

	}
	// ...
}

async computeAsync( computeNodes, dispatchSize = [ 0, 0, 0 ] ) {

	if ( this._initialized === false ) await this.init();
	this.compute( computeNodes, dispatchSize );

}
```

[重构思路] 在 Backend 基类与所有实现中统一新签名，WebGL 侧按 dispatchSize 换算为实例数（dispatchSize 各分量与 workgroupSize 相乘得总 invocation 数），或至少在不支持时显式 warn。
代码示例：
```js
// Base
compute( /*computeGroup, computeNode, computeBindings, computePipeline, dispatchSize*/ ) { }

// WebGLBackend
compute( computeGroup, computeNode, bindings, pipeline, dispatchSize = [ 0, 0, 0 ] ) {

	const [ wgX, wgY, wgZ ] = computeNode.workgroupSize;
	const hasExplicit = dispatchSize[ 0 ] > 0 && dispatchSize[ 1 ] > 0 && dispatchSize[ 2 ] > 0;
	const count = hasExplicit ? dispatchSize[ 0 ] * dispatchSize[ 1 ] * dispatchSize[ 2 ] * wgX * wgY * wgZ : computeNode.count;
	// ... drawArrays( gl.POINTS, 0, count )
}
```

[重构思路] 两条分支共用同一个 clamp/校验工具，超限时抛出具名错误（或按自动分支逻辑切分 y 维）。
代码示例：
```js
const maxDim = this.device.limits.maxComputeWorkgroupsPerDimension;
if ( isValid ) {

	if ( dispatchSize[ 0 ] > maxDim || dispatchSize[ 1 ] > maxDim || dispatchSize[ 2 ] > maxDim ) {

		throw new Error( 'THREE.WebGPUBackend: dispatchSize exceeds maxComputeWorkgroupsPerDimension (' + maxDim + ').' );

	}

	passEncoderGPU.dispatchWorkgroups( dispatchSize[ 0 ], dispatchSize[ 1 ], dispatchSize[ 2 ] );

} else { /* 原逻辑 */ }
```

[重构思路] 在 ComputeNode 构造函数内统一归一化 workgroupSize（补 1 到三元），把校验前移并给出带来源的可读错误；后端的校验改为“归一化后仍非法才报错”。
代码示例：
```js
// ComputeNode constructor
if ( Array.isArray( workgroupSize ) && workgroupSize.length > 0 && workgroupSize.length < 3 ) {

	workgroupSize = [ workgroupSize[ 0 ], workgroupSize[ 1 ] ?? 1, workgroupSize[ 2 ] ?? 1 ];

}
this.workgroupSize = workgroupSize;

// WGSLNodeBuilder
if ( workgroupSize.length !== 3 ) throw new Error( 'THREE.WGSLNodeBuilder: workgroupSize must be normalized to [ x, y, z ].' );
```

[重构思路] 用独立局部变量分别承载“用户 dispatch 尺寸数组”和“节点缓存 dispatch 对象”，删除不再被读取的 computeNodeData.dispatchSize 缓存。
代码示例：
```js
const maxDim = this.device.limits.maxComputeWorkgroupsPerDimension;

if ( isValid ) {

	passEncoderGPU.dispatchWorkgroups( dispatchSize[ 0 ], dispatchSize[ 1 ], dispatchSize[ 2 ] );

} else {

	const dispatch = computeNodeData.dispatchSize || ( computeNodeData.dispatchSize = { x: 0, y: 1, z: 1 } );
	if ( computeNode.dispatchCount > maxDim ) {

		dispatch.x = Math.min( computeNode.dispatchCount, maxDim );
		dispatch.y = Math.ceil( computeNode.dispatchCount / maxDim );

	} else {

		dispatch.x = computeNode.dispatchCount;

	}
	passEncoderGPU.dispatchWorkgroups( dispatch.x, dispatch.y, dispatch.z );

}
```

[重构思路] 显式限制或支持按节点指定：当 computeList.length > 1 且 dispatchSize 非默认值时给出 warn，或把参数改为可选的按节点映射（如数组的数组 / 函数）。
代码示例：
```js
compute( computeNodes, dispatchSize = [ 0, 0, 0 ] ) {

	const computeList = Array.isArray( computeNodes ) ? computeNodes : [ computeNodes ];

	if ( computeList.length > 1 && dispatchSize[ 0 ] + dispatchSize[ 1 ] + dispatchSize[ 2 ] > 0 ) {

		console.warn( 'THREE.Renderer: .compute() dispatchSize applies to every compute node in the list.' );

	}
	// ...
}
```
